400	pub(crate) struct Position {
401	    pub line: usize,
402	}
403	
404	impl Rpc {
405	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
406	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
407	    /// numeric ones.
408	    pub(crate) async fn prepare(
409	        client: &Client,
410	        deadline: Duration,
411	        tsconfig: Option<&str>,
412	    ) -> Result<Value, CallError> {
413	        let rpc = Rpc {
414	            client: client.clone(),
415	            deadline,
416	            snapshot: 0,
417	            project: String::new(),
418	            options: Value::Null,
419	            recording: None,
420	            calls: Arc::default(),
421	            others: Mutex::default(),
422	        };
423	        rpc.call("initialize", &Value::Null).await?;
424	        Ok(match tsconfig {
425	            Some(file) => {
426	                let parsed: Value = decode(&rpc.call("parseConfigFile", &json!({ "file": file })).await?)?;
427	                parsed.get("options").cloned().unwrap_or_else(default_options)
428	            }
429	            None => default_options(),
430	        })
431	    }
432	
433	    /// One snapshot of a program over `root_files` for each of `count` lanes (one when `count` is at most one), in a
434	    /// session it initializes first ([`Rpc::prepare`]), with one session bound to each, the `n`th asking down the
435	    /// checker's `n`th lane ([`Client::lane`]): a checker that answers requests about different snapshots at once
436	    /// ([`crate::checker`]) answers the sessions in parallel. Each lane has a snapshot of its own because the checker
437	    /// registers the symbols, types and signatures it hands out in one table per snapshot, behind one lock: two programs
438	    /// of one snapshot wait for each other on it. The first lane's snapshot is built from the disk; each other one is
439	    /// derived from it ([`Rpc::beside`]), so every program reads the same text of every file. They share the request
440	    /// counts and the recording; [`Rpc::release`] on the first releases every snapshot.
441	    pub(crate) async fn open_programs(
442	        client: Client,
443	        deadline: Duration,
444	        tsconfig: Option<&str>,
445	        root_files: &[String],
446	        record: bool,
447	        count: usize,
448	    ) -> Result<Vec<Rpc>, CallError> {
449	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
450	        let first = Rpc::open_with(client.lane(0), deadline, &options, root_files, record).await?;
451	        let mut lanes: Vec<Rpc> = Vec::with_capacity(count.max(1));
452	        for lane in 1..count {
453	            match first.beside(client.lane(lane), root_files).await {
454	                Ok(rpc) => lanes.push(rpc),
455	                Err(error) => {
456	                    // Nothing will hold the snapshots made so far to release them later.
457	                    first.release().await;
458	                    for opened in &lanes {
459	                        opened.release().await;
460	                    }
461	                    return Err(error);
462	                }
463	            }
464	        }
465	        let others = lanes.iter().map(|rpc| rpc.snapshot).collect();
466	        lanes.insert(0, Rpc { others: Mutex::new(others), ..first });
467	        Ok(lanes)
468	    }
469	
470	    /// A snapshot of its own for a program over `root_files` beside this one's, asked through `client`: derived from
471	    /// this snapshot (`updateSnapshot` with `createPrograms`), it reads every file as this one holds it, from the files
472	    /// this snapshot has read and parsed, and does not go to the disk again. It shares the request counts and the
473	    /// recording; it is released on its own.
474	    async fn beside(&self, client: Client, root_files: &[String]) -> Result<Rpc, CallError> {
475	        let changes = json!({
476	            "createPrograms": [{ "rootFiles": root_files, "compilerOptions": self.options }],
477	            "ensurePrograms": true,
478	        });
479	        let response: SnapshotResponse =
480	            decode(&self.call("updateSnapshot", &json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
481	        let rpc = Rpc {
482	            client,
483	            deadline: self.deadline,
484	            snapshot: response.snapshot,
485	            project: String::new(),
486	            options: self.options.clone(),
487	            recording: self.recording.clone(),
488	            calls: self.calls.clone(),
489	            others: Mutex::default(),
490	        };
491	        // The response lists the programs the update made or changed: the one created, not this one's.
492	        let Some(project) = response.projects.into_iter().find(|project| project.id != self.project) else {
493	            // Nothing will hold this snapshot to release it later.
494	            rpc.release().await;
495	            return Err(CallError::Rejected("updateSnapshot created no program".to_string()));
496	        };
497	        Ok(Rpc { project: project.id, ..rpc })
498	    }
499	
500	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
501	    pub(crate) async fn open_with(
502	        client: Client,
503	        deadline: Duration,
504	        options: &Value,
505	        root_files: &[String],
506	        record: bool,
507	    ) -> Result<Rpc, CallError> {
508	        let rpc = Rpc {
509	            client,
510	            deadline,
511	            snapshot: 0,
512	            project: String::new(),
513	            options: options.clone(),
514	            recording: record.then(Arc::default),
515	            calls: Arc::default(),
516	            others: Mutex::default(),
517	        };
518	        rpc.created(json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] })).await
519	    }
520	
521	    /// A snapshot of a program rooted at `files` alone, held in the checker's memory and never written to disk (see
522	    /// [`Rpc::layered`]), in a session [`Rpc::prepare`] already initialized.
523	    pub(crate) async fn open_in_memory(
524	        client: Client,
525	        deadline: Duration,
526	        options: &Value,
527	        files: &[(String, String)],
528	    ) -> Result<Rpc, CallError> {
529	        let session = Rpc {
530	            client,
531	            deadline,
532	            snapshot: 0,
533	            project: String::new(),
534	            options: options.clone(),
535	            recording: None,
536	            calls: Arc::default(),
537	            others: Mutex::default(),
538	        };
539	        let layer = in_memory_layer(files);
540	        let roots: Vec<&String> = files.iter().map(|(path, _)| path).collect();
541	        session
542	            .created(json!({
543	                "fileSystem": layer,
544	                "createPrograms": [{ "rootFiles": roots, "compilerOptions": options }],
545	            }))
546	            .await
547	    }
548	
549	    /// The snapshot after this one with `files` added, held in the checker's memory and never written to disk (each is
550	    /// a root file, keyed by its absolute path), and this one's program rooted at `root_files` and them instead, built at
551	    /// once (`updateSnapshot` with `reconfigurePrograms`). It is derived from this snapshot, so it reads every other file
552	    /// as this one holds it, from the files this one has read and parsed, and holds one program: a fresh `createSnapshot`
553	    /// read and parsed every file again into a second whole program while this one's was still alive. The calls on it
554	    /// count, and are recorded, with this one's; it is released on its own, and this one stays alive until it is.
555	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
556	        let mut roots = root_files.to_vec();
557	        roots.extend(files.iter().map(|(path, _)| path.clone()));
558	        let changes = json!({
559	            "fileSystem": in_memory_layer(files),
560	            "reconfigurePrograms": [{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }],
561	            "ensurePrograms": true,
562	        });
563	        let response: SnapshotResponse =
564	            decode(&self.call("updateSnapshot", &json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
565	        // The response lists the projects the update replaced: the reconfigured one, which may keep its id.
566	        let mut projects = response.projects.into_iter().map(|project| project.id);
567	        let project = match projects.len() {
568	            0 => self.project.clone(),
569	            1 => projects.next().unwrap_or_default(),
570	            _ => match projects.find(|id| *id == self.project) {
571	                Some(id) => id,
572	                None => {
573	                    // Nothing will hold this snapshot to release it later.
574	                    self.call("release", &json!({ "snapshot": response.snapshot })).await.ok();
575	                    return Err(CallError::Rejected(
576	                        "updateSnapshot changed programs other than the one reconfigured".to_string(),
577	                    ));
578	                }
579	            },
580	        };
581	        Ok(Rpc {
582	            client: self.client.clone(),
583	            deadline: self.deadline,
584	            snapshot: response.snapshot,
585	            project,
586	            options: self.options.clone(),
587	            recording: self.recording.clone(),
588	            calls: self.calls.clone(),
589	            others: Mutex::default(),
590	        })
591	    }
592	
593	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
594	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
595	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
596	    /// only when it is rebuilt. This snapshot stays alive until it is released.
597	    pub(crate) async fn updated(
598	        &self,
599	        changed: &[String],
600	        deleted: &[String],
601	        roots: Option<&[String]>,
602	    ) -> Result<Rpc, CallError> {
603	        let mut changes = serde_json::Map::new();
604	        if !changed.is_empty() || !deleted.is_empty() {
605	            changes.insert("fileNotifications".to_string(), json!({ "changed": changed, "deleted": deleted }));
606	        }
607	        if let Some(roots) = roots {
608	            changes.insert(
609	                "reconfigurePrograms".to_string(),
610	                json!([{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }]),
611	            );
612	        }
613	        changes.insert("ensurePrograms".to_string(), Value::Bool(true));
614	        let response: SnapshotResponse =
615	            decode(&self.call("updateSnapshot", &json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
616	        // The response lists only the projects it replaced; the synthetic program keeps its id.
617	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
618	        Ok(Rpc {
619	            client: self.client.clone(),
620	            deadline: self.deadline,
621	            snapshot: response.snapshot,
622	            project,
623	            options: self.options.clone(),
624	            recording: self.recording.clone(),
625	            calls: Arc::default(),
626	            others: Mutex::default(),
627	        })
628	    }
629	
630	    /// Runs `work` on the checker thread this session asks ([`Client::run_on_thread`]), given this session as that
631	    /// thread asks it, in place; each request is bounded by this session's deadline.
632	    pub(crate) async fn run_on_thread<T: Send + 'static>(
633	        self: &Arc<Self>,
634	        work: impl FnOnce(Arc<Rpc>) -> T + Send + 'static,
635	    ) -> Result<T, CallError> {
636	        let this = Arc::clone(self);
637	        let run = self.client.run_on_thread(self.deadline, move |client| work(Arc::new(this.through(client))));
638	        run.await.map_err(classify)
639	    }
640	
641	    /// This session asked through `client`: the same snapshot and project, counts and recording.
642	    fn through(&self, client: Client) -> Rpc {
643	        Rpc {
644	            client,
645	            deadline: self.deadline,
646	            snapshot: self.snapshot,
647	            project: self.project.clone(),
648	            options: self.options.clone(),
649	            recording: self.recording.clone(),
650	            calls: self.calls.clone(),
651	            others: Mutex::default(),
652	        }
653	    }
654	
655	    /// The snapshot this session asks about.
656	    #[cfg(test)]
657	    pub(crate) fn snapshot_id(&self) -> u64 {
658	        self.snapshot
659	    }
660	
661	    /// Every file the snapshot's program read, as the checker names them.
662	    pub(crate) async fn source_file_names(&self) -> Result<Vec<String>, CallError> {
663	        self.scoped("getSourceFileNames", Asking::Nothing {}).await
664	    }
665	
666	    /// This session bound to the snapshot `createSnapshot` makes from `params`, and to its one project.
667	    async fn created(mut self, params: Value) -> Result<Rpc, CallError> {
668	        let response: SnapshotResponse = decode(&self.call("createSnapshot", &params).await?)?;
669	        self.snapshot = response.snapshot;
670	        let Some(project) = response.projects.into_iter().next() else {
671	            // Nothing will hold this snapshot to release it later.
672	            self.release().await;
673	            return Err(CallError::Rejected("createSnapshot returned no project".to_string()));
674	        };
675	        self.project = project.id;
676	        Ok(self)
677	    }
678	
679	    /// Releases the snapshot, and those of the lanes opened beside it ([`Rpc::open_programs`]).
680	    pub(crate) async fn release(&self) {
681	        let lanes = self.take_lanes();
682	        for snapshot in std::iter::once(self.snapshot).chain(lanes) {
683	            self.call("release", &json!({ "snapshot": snapshot })).await.ok();
684	        }
685	    }
686	
687	    /// Releases the snapshots of the lanes opened beside this one ([`Rpc::open_programs`]) and keeps this one's: what
688	    /// they hold (each lane's program and its checker's caches) is freed before the work that follows the lanes. Each is
689	    /// released once, here or by [`Rpc::release`], never by both. Nothing may ask a lane after.
690	    pub(crate) async fn release_lanes(&self) {
691	        for snapshot in self.take_lanes() {
692	            self.call("release", &json!({ "snapshot": snapshot })).await.ok();
693	        }
694	    }
695	
696	    /// The lanes' snapshots not yet released, which are then no longer this one's to release.
697	    fn take_lanes(&self) -> Vec<u64> {
698	        std::mem::take(&mut *self.others.lock().unwrap_or_else(std::sync::PoisonError::into_inner))
699	    }
700	
701	    /// The recorded calls as a JSON array, or `None` when recording was off.
702	    pub(crate) fn recording(&self) -> Option<Value> {
703	        let log = self.recording.as_ref()?.lock().ok()?;
704	        Some(Value::Array(log.clone()))
705	    }
706	
707	    /// Requests sent so far, by method.
708	    pub(crate) fn calls(&self) -> BTreeMap<&'static str, u64> {
709	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
710	    }
711	
712	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
713	    /// expects. The parameters are written straight to the text the checker reads.
714	    async fn call(&self, method: &'static str, params: &impl Serialize) -> Result<Box<RawValue>, CallError> {
715	        // A release gives memory back, so it is sent past the heap budget too.
716	        if method != "release" {
717	            crate::heap::step()?;
718	        }
719	        if let Ok(mut calls) = self.calls.lock() {
720	            *calls.entry(method).or_default() += 1;
721	        }
722	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
723	        let params = serde_json::to_vec(params)
724	            .map_err(|error| CallError::Fatal(format!("failed to serialize a request: {error}")))?;
725	        let Some(log) = &self.recording else {
726	            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
727	        };
728	        let sent: Value = serde_json::from_slice(&params).unwrap_or(Value::Null);
729	        let answer = self.client.request_raw(method, params, self.deadline).await.map_err(classify)?;
730	        let (params, result): (Value, Value) = (sent, decode(&answer)?);
731	        if let Ok(mut log) = log.lock() {
732	            log.push(json!({ "method": method, "params": params, "result": result }));
733	        }
734	        Ok(answer)
735	    }
