822	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
823	    /// that may legitimately fail.
824	    pub(crate) async fn batch(
825	        &self,
826	        requests: Vec<(&'static str, Asking<'_>)>,
827	    ) -> Result<Vec<Box<RawValue>>, CallError> {
828	        let wanted = requests.len();
829	        let scoped: Vec<Batched<'_, Asking<'_>>> = requests
830	            .into_iter()
831	            .map(|(method, extra)| Batched {
832	                method,
833	                params: Scoped { project: &self.project, snapshot: self.snapshot, extra },
834	            })
835	            .collect();
836	        let mut answers = Vec::with_capacity(wanted);
837	        let mut token: Option<String> = None;
838	        loop {
839	            let params = BatchParams { requests: &scoped, continuation_token: token.as_deref() };
840	            let page: BatchPage = decode(&self.call("batchRequests", &params).await?)?;
841	            for response in page.responses {
842	                if let Some(error) = response.error {
843	                    return Err(CallError::Rejected(error));
844	                }
845	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
846	            }
847	            match page.continuation_token {
848	                Some(next) => token = Some(next),
849	                None => break,
850	            }
851	        }
852	        if answers.len() != wanted {
853	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
854	        }
855	        Ok(answers)
856	    }
