            let Some(entry) = snapshots.get_mut(&handle) else {
                return Err(ApiError::client(format!("snapshot {handle} not found")));
            };
            entry.1 -= 1;
            if entry.1 == 0 { snapshots.remove(&handle) } else { None }
        };
